head.script:
scwin.screenId = "jldfil30201";

///////// 1. 변수 및 선언 영역 /////////

scwin.koList = $c.util.getComponent('koList');

scwin.enList = $c.util.getComponent('enList');

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.i = undefined;


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init = function () {
    /* sdd-asis-lifecycle:begin init — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.close();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.init();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30201.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil30201.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.rd_language_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.rd_language_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin rd_language_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.checkValue('ko')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30201.rd_language_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_Confirm_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Confirm_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Confirm_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.confirm()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30201.btn_Confirm_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Confirm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Confirm = async function () {
    const sbmOptions = {
        id: "tx_fn_Confirm",
        method: "post",
        action: "/issue/certificate.do",
        ref: "dma_ConfirmReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil30201.tx_fn_Confirm" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.confirm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.confirm = async function () {
    /* sdd-asis-lifecycle:begin fn_Confirm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let useCode = "";
    let useValue = "";
    for (scwin.i = 0; scwin.i < 23; scwin.i++) {
        if ((String($c.util.getComponent(["ipt_useGubun", "ipt_useGubun_2", "ipt_useGubun_3", "ipt_useGubun_4", "ipt_useGubun_5", "ipt_useGubun_6", "ipt_useGubun_7", "ipt_useGubun_8", "ipt_useGubun_9", "ipt_useGubun_10", "ipt_useGubun_11", "ipt_useGubun_12", "ipt_useGubun_13", "ipt_useGubun_14", "ipt_useGubun_15", "ipt_useGubun_16", "ipt_useGubun_17", "ipt_useGubun_18", "ipt_useGubun_19", "ipt_useGubun_20", "ipt_useGubun_21", "ipt_useGubun_22", "ipt_useGubun_23"][scwin.i]).getValue() || '') !== '') === true) {
            useCode = useCode + $c.util.getComponent(["ipt_useGubun", "ipt_useGubun_2", "ipt_useGubun_3", "ipt_useGubun_4", "ipt_useGubun_5", "ipt_useGubun_6", "ipt_useGubun_7", "ipt_useGubun_8", "ipt_useGubun_9", "ipt_useGubun_10", "ipt_useGubun_11", "ipt_useGubun_12", "ipt_useGubun_13", "ipt_useGubun_14", "ipt_useGubun_15", "ipt_useGubun_16", "ipt_useGubun_17", "ipt_useGubun_18", "ipt_useGubun_19", "ipt_useGubun_20", "ipt_useGubun_21", "ipt_useGubun_22", "ipt_useGubun_23"][scwin.i]).getValue() + ",";
            useValue = useValue + scwin.getUseValue($c.util.getComponent(["ipt_useGubun", "ipt_useGubun_2", "ipt_useGubun_3", "ipt_useGubun_4", "ipt_useGubun_5", "ipt_useGubun_6", "ipt_useGubun_7", "ipt_useGubun_8", "ipt_useGubun_9", "ipt_useGubun_10", "ipt_useGubun_11", "ipt_useGubun_12", "ipt_useGubun_13", "ipt_useGubun_14", "ipt_useGubun_15", "ipt_useGubun_16", "ipt_useGubun_17", "ipt_useGubun_18", "ipt_useGubun_19", "ipt_useGubun_20", "ipt_useGubun_21", "ipt_useGubun_22", "ipt_useGubun_23"][scwin.i]).getValue()) + ",";
        }
    }
    $c.util.getComponent('dma_ConfirmReq').set('useCode', useCode);
    $c.util.getComponent('dma_ConfirmReq').set('useValue', useValue);
    $c.util.getComponent('dma_ConfirmReq').set('listCertTpCd', "1");
    if (await scwin.elementChk()) {
        if (await $c.win.confirm("등록하시겠습니까?")) {
            (document.createForm || { elements: [] }).action = '/issue/certificate.do';
            $c.util.getComponent('dma_ConfirmReq').set('method', "registerCertificateNoList");
            await scwin.tx_fn_Confirm();
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.close
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.close = function () {
    /* sdd-asis-lifecycle:begin fn_close — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})) !== scwin && typeof (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})).fn_load === 'function' ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})).fn_load() : void 0), $c.win.closePopup([]));
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.elementChk
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.elementChk = async function () {
    /* sdd-asis-lifecycle:begin fn_ElementChk — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const form = (document.createForm || { elements: [] });
    if ($c.util.getComponent('dma_ConfirmReq').get('korengGubun')== null || $c.util.getComponent('dma_ConfirmReq').get('korengGubun')=== '') {
        await $c.win.alert("한영구분을 선택해주십시오.");
        return false;
    }
    if ($c.util.getComponent('dma_ConfirmReq').get('useCode')== null || $c.util.getComponent('dma_ConfirmReq').get('useCode')=== '') {
        await $c.win.alert("용도 구분을 1개이상 선택해주십시오.");
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getUseValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param code
 * @returns
 * @hidden N
*/
scwin.getUseValue = function (code) {
    /* sdd-asis-lifecycle:begin fn_getUseValue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (code === "01") {
        return "비자발급신청용";
    } else {
        if (code === "02") {
            return "법원제출용";
        } else {
            if (code === "03") {
                return "관공서제출용";
            } else {
                if (code === "04") {
                    return "은행제출용";
                } else {
                    if (code === "05") {
                        return "회사제출용";
                    } else {
                        if (code === "06") {
                            return "내부업무용";
                        } else {
                            if (code === "07") {
                                return "공증용";
                            } else {
                                if (code === "08") {
                                    return "계약체결용";
                                } else {
                                    if (code === "09") {
                                        return "확인용";
                                    } else {
                                        if (code === "10") {
                                            return "등기용";
                                        } else {
                                            if (code === "11") {
                                                return "세관제출용";
                                            } else {
                                                if (code === "12") {
                                                    return "사외이사의 대학교무처 제출용";
                                                } else {
                                                    if (code === "13") {
                                                        return "회사비치용";
                                                    } else {
                                                        if (code === "14") {
                                                            return "여권발급용";
                                                        } else {
                                                            if (code === "15") {
                                                                return "주주총회 공증용";
                                                            } else {
                                                                if (code === "16") {
                                                                    return "사업등기용";
                                                                } else {
                                                                    if (code === "17") {
                                                                        return "합병등기용";
                                                                    } else {
                                                                        if (code === "18") {
                                                                            return "국세심판소제출용";
                                                                        } else {
                                                                            if (code === "20") {
                                                                                return "Applying for Visa";
                                                                            } else {
                                                                                if (code === "21") {
                                                                                    return "New Account Opening";
                                                                                } else {
                                                                                    if (code === "22") {
                                                                                        return "EB follow up";
                                                                                    } else {
                                                                                        if (code === "23") {
                                                                                            return "Certification";
                                                                                        } else {
                                                                                            if (code === "24") {
                                                                                                return "For Submission";
                                                                                            } else {
                                                                                                return "기타";
                                                                                            }
                                                                                        }
                                                                                    }
                                                                                }
                                                                            }
                                                                        }
                                                                    }
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param lang
 * @returns
 * @hidden N
*/
scwin.checkValue = function (lang) {
    /* sdd-asis-lifecycle:begin fn_checkValue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let kk = "";
    kk = $c.util.getComponent('rd_language').getValue();
    $c.util.getComponent('dma_ConfirmReq').set('korengGubun', kk);
    if (lang === "en") {
        scwin.enList.setStyle("display", "block");
        scwin.koList.setStyle("display", "none");
        $("#koList").children("input[type=checkbox][checked]").each(function() {
                $(this).attr('checked', false);
        });
    } else {
        scwin.enList.setStyle("display", "none");
        scwin.koList.setStyle("display", "block");
        $("#enList").children("input[type=checkbox][checked]").each(function() {
                $(this).attr('checked', false);
        });
    }
    /* sdd-asis-lifecycle:end */
};
